INSERT INTO `chat_messages` (`id`, `conversation_id`, `role`, `content`, `model`, `tokens`, `duration_ms`, `created_at`, `attachments`) VALUES
(71, 13, 'user', 'Tìm sân bóng đá đang hoạt động', NULL, NULL, NULL, '2026-08-25 03:51:18', NULL),
(72, 13, 'assistant', 'Xin chào Admin gà quá! Tôi đã kiểm tra danh sách và có một số sân bóng đá đang hoạt động phù hợp với khu vực của bạn. Mình sẽ gợi ý cho bạn sân **Nguyen Vu Hieu** tại K596 Hoàng Diệu, Phường Hòa Cường Bắc, Quận Hải Châu, Thành phố Đà Nẵng. Đây là một địa điểm thuận tiện và giá cả hợp lý. \n\nChèn thẻ sân:\n[COURT_CARD:{\"id\":11,\"name\":\"Sân đá bóng 3\",\"vendor\":\"Nguyen Vu Hieu\",\"address\":\"K596 Hoang Dieu, Phường Hòa Cường Bắc, Quận Hải Châu, Thành phố Đà Nẵng\",\"hours\":\"08:00 - 23:00\",\"price\":\"50.000 ₫/giờ\",\"sport\":\"Bóng đá\",\"image\":\"\"}]\n\nBạn có muốn đặt sân tại đây không? Hiện tại số dư ví của bạn là 2.841.250 ₫. Bạn có thể thanh toán trực tiếp qua ví hoặc quét mã PayOS VietQR khi đặt sân nhé!', 'qwen2.5:7b', NULL, 7777, '2026-08-25 03:51:26', NULL),
(103, 19, 'user', 'Tìm sân cầu lông chất lượng gần tôi', NULL, NULL, NULL, '2026-08-28 02:40:02', NULL),
(104, 19, 'assistant', 'Chào vuhieu27! Dựa trên vị trí của bạn tại đường Hoàng Văn Thụ, Quận Hải Châu, Đà Nẵng, mình đã tìm thấy một sân cầu lông chất lượng cao, nằm ngay trong quận Hải Châu để bạn cực kỳ thuận tiện di chuyển:\n\n[COURT_CARD:{\"id\":46,\"name\":\"Sân Cầu Lông 2\",\"vendor\":\"Nguyen Vu Hieu\",\"address\":\"K596 Hoang Dieu, Phường Hòa Cường Bắc, Quận Hải Châu, Thành phố Đà Nẵng\",\"hours\":\"08:00 - 23:00\",\"price\":\"150.000 ₫/giờ\",\"sport\":\"Cầu Lông\",\"image\":\"\"}]\n\nSân được trang bị thảm chống trơn trượt đạt chuẩn, hệ thống đèn chiếu sáng hiện đại chống chói, giúp bạn có những pha cầu chuẩn xác nhất. \n\nHiện tại số dư ví của bạn là 0 ₫. Bạn có thể thanh toán trực tiếp qua ví hoặc quét mã PayOS VietQR khi đặt sân nhé!\n\nBạn dự định ra sân vào ngày nào và khung giờ nào? Hãy cho mình biết để mình kiểm tra tình trạng trống của sân và hỗ trợ bạn đặt lịch giữ chỗ ngay nhé!', 'gemini-3.5-flash', NULL, 9755, '2026-08-28 02:40:12', NULL),
(111, 19, 'user', 'aloalo', NULL, NULL, NULL, '2026-08-28 02:45:10', NULL),
(112, 19, 'assistant', 'Dạ, Sporting ONE AI nghe đây vuhieu27 ơi! 🏸\n\nMình vẫn đang ở đây để hỗ trợ bạn. Bạn có cần mình kiểm tra giờ trống cho **Sân Cầu Lông 2** (đường Hoàng Diệu, Hải Châu) gần bạn, hoặc cần tìm thêm sân của môn thể thao nào khác không? \n\nHãy cho mình biết ngày và giờ bạn muốn ra sân để mình lên lịch ngay nhé!', 'gemini-3.5-flash', NULL, 7840, '2026-08-28 02:45:18', NULL),
