INSERT INTO `notifications` (`id`, `notification_name`, `contents`, `created_at`, `user_id`, `ondeleted`) VALUES
(3, 'Alo Alo', 'hiu', '2026-08-13 21:49:35', 18, NULL),
(4, 'Yêu cầu rút tiền #64 đã được phê duyệt', 'Yêu cầu rút 400.000 Xu của bạn đã được Admin phê duyệt thành công. Tiền sẽ sớm được chuyển vào tài khoản ngân hàng của bạn.', '2026-08-14 03:31:35', 18, NULL),
(5, 'Yêu cầu rút tiền #65 đã bị từ chối', 'Yêu cầu rút 65.000 Xu (Mã GD: WD03722421) của bạn đã bị từ chối xét duyệt.\nLý do từ chối: Đéo cho rút\n.\nToàn bộ 65.000 Xu đã được hoàn lại 100\\\% vào Ví Sporting ONE của bạn.', '2026-08-14 03:35:35', 18, NULL),
(6, 'Alo Alo', 'hiu', '2026-08-14 03:37:32', 18, NULL),
(7, '[Sporting ONE] Hoàn tiền đơn đặt sân #98', 'Sân thi đấu \"Sân đá bóng 1\" hiện đã bị xóa khỏi hệ thống. Chúng tôi đã hoàn trả 50.000 Xu vào ví tài khoản (Wallet) cho đơn đặt sân #98 (09:00 21/8/2026 - 10:00 21/8/2026) của bạn. Vui lòng kiểm tra ví tài khoản của bạn!', '2026-08-20 14:59:44', 18, NULL),
(8, '[Sporting ONE] Hoàn tiền đơn đặt sân #99', 'Sân thi đấu \"Sân đá bóng 7\" hiện đã bị xóa khỏi hệ thống. Chúng tôi đã hoàn trả 50.000 Xu vào ví tài khoản (Wallet) cho đơn đặt sân #99 (11:00 21/8/2026 - 12:00 21/8/2026) của bạn. Vui lòng kiểm tra ví tài khoản của bạn!', '2026-08-20 15:01:37', 18, NULL),
(9, '[Sporting ONE] Hoàn tiền đơn đặt sân', 'Sân thi đấu \"Sân đá bóng 7\" hiện đã bị xóa khỏi hệ thống. Chúng tôi đã hoàn trả 75.000 Xu vào ví tài khoản (Wallet) cho đơn đặt sân #100 (11:00 21/8/2026 - 12:30 21/8/2026) của bạn. Vui lòng kiểm tra ví tài khoản của bạn!', '2026-08-20 15:22:48', 18, NULL),
(10, 'Yêu Cầu Hoàn Tiền Đã Được Chấp Thuận', 'Chủ sân \"Nguyen Vu Hieu\" đã duyệt yêu cầu hoàn 100.000 Xu vào ví tài khoản cho đơn đặt sân \"Sân đá bóng 2\" (#BK-101). Vui lòng kiểm tra số dư ví tài khoản của bạn!', '2026-08-20 16:03:52', 15, NULL),
(11, 'Yêu Cầu Hoàn Tiền Bị Từ Chối', 'Chủ sân \"Nguyen Vu Hieu\" đã từ chối yêu cầu hủy và hoàn tiền cho đơn đặt sân \"Sân đá bóng 2\" (#BK-102) với lý do: \"Bạn không thể huỷ đơn ngay lúc này\". Lịch đặt sân của bạn tiếp tục được giữ nguyên trạng thái Đã Thanh Toán.', '2026-08-20 16:09:48', 15, NULL),
(12, '[Sporting ONE] Hoàn tiền đơn đặt sân', 'Sân thi đấu \"Sân đá bóng 2\" hiện đã bị xóa khỏi hệ thống. Chúng tôi đã hoàn trả 150.000 Xu vào ví tài khoản (Wallet) cho đơn đặt sân (17:15 25/8/2026 - 18:45 25/8/2026) của bạn. Vui lòng kiểm tra ví tài khoản của bạn!', '2026-08-25 03:14:30', 18, NULL),
(13, 'Yêu Cầu Hoàn Tiền Bị Từ Chối', 'Chủ sân \"Nguyen Vu Hieu\" đã từ chối yêu cầu hủy và hoàn tiền cho đơn đặt sân \"Sân đá bóng 3\" (#BK-106) với lý do: \"Theo quy định đặt sân, qua 2 tiếng ko huỷ thì ko được hoàn\". Lịch đặt sân của bạn tiếp tục được giữ nguyên trạng thái Đã Thanh Toán.', '2026-08-25 03:16:58', 15, NULL),
(14, 'Hủy Đơn & Hoàn Tiền Thành Công', 'Bạn đã hủy thành công đơn đặt sân \"Sân đá bóng 3\" (#BK-114). Hệ thống đã tự động hoàn 100.000 Xu vào ví tài khoản của bạn!', '2026-08-26 05:12:49', 15, NULL),
(15, 'Hủy Gói Tháng & Hoàn Tiền Thành Công', 'Bạn đã hủy thành công gói đặt sân tháng \"Sân bóng chuyền 3\" (#BM-1). Hệ thống đã tự động hoàn 1.000.000 Xu vào ví tài khoản của bạn!', '2026-08-31 08:25:42', 15, NULL),
(16, 'Vendor registration profile \"1\" has been rejected', 'Your sports venue partner registration profile \"1\" has been rejected.\nRejection reason: bị huỷ.\nPlease check your profile information and venue licenses to update and resubmit for approval.', '2026-08-31 09:48:25', 18, NULL),
(17, 'Hủy Đơn & Hoàn Tiền Thành Công', 'Bạn đã hủy thành công đơn đặt sân \"Sân đá bóng 3\" (#BK-126). Hệ thống đã tự động hoàn 75.000 Xu vào ví tài khoản của bạn!', '2026-09-04 03:13:02', 15, NULL),
(18, '[Sporting ONE] Hoàn tiền đơn đặt sân', 'Sân thi đấu \"Sân Cầu Lông 2\" hiện đã bị xóa khỏi hệ thống. Chúng tôi đã hoàn trả 150.000 Xu vào ví tài khoản (Wallet) cho đơn đặt sân (11:00 7/9/2026 - 12:00 7/9/2026) của bạn. Vui lòng kiểm tra ví tài khoản của bạn!', '2026-09-06 19:14:09', 18, NULL);
